import{_ as s,c as t,o as e,ag as i}from"./chunks/framework.Sr95JMjc.js";const k=JSON.parse('{"title":"AWS EC2 호스트이름","description":"","frontmatter":{"title":"AWS EC2 호스트이름","date":"2025-01-10T23:00+09:00","tags":["EC2 Hostname","hostnamectl","/etc/hostname"]},"headers":[],"relativePath":"posts/ec2-hostname.md","filePath":"posts/ec2-hostname.md","lastUpdated":1777596490000}'),n={name:"posts/ec2-hostname.md"};function l(h,a,o,r,p,c){return e(),t("div",null,[...a[0]||(a[0]=[i(`<p>최근 고객사의 시계열 데이터베이스 서버에 있는 데이터를 최적화하고 삭제되는 데이터의 일부를 CSV로 추출하여 S3 버킷에 백업하는 유지보수 작업을 수행하고 있습니다. 해당 시계열 데이터베이스는 상용 기술로 라이센스 확인을 위해 외부 통신을 수행하는데 이 과정에서 서버 호스트이름을 라이센스 발급 시 지정된 값으로 지정해야합니다.</p><p>고객사 인프라팀에서 복제된 서버를 제공해주었지만 호스트이름이 임의로 설정되어있기 때문에 호스트이름을 <u>hostnamectl</u>을 통해 변경해야 했습니다. 고객사 환경에 접근 통제를 위해 <u>HIWARE(HI-TAM)</u>이 적용되어 있어 작업 진행 시 서버 호스트이름 변경이 접근 통제에 영향을 미치지 않음을 확인받았습니다.</p><h4 id="hostnamectl-을-통한-호스트이름-변경" tabindex="-1">hostnamectl 을 통한 호스트이름 변경 <a class="header-anchor" href="#hostnamectl-을-통한-호스트이름-변경" aria-label="Permalink to &quot;hostnamectl 을 통한 호스트이름 변경&quot;">​</a></h4><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hostnamectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-hostname</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsdb.local</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[ec2-user@tsdb </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]$ hostname -f</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tsdb.local</span></span></code></pre></div><p>EC2 인스턴스가 이미 만들어진 경우이므로 서버 접속 후에 hostnamectl 명령어를 통해 호스트이름을 변경할 수 있습니다. 서버 재부팅은 수행하지 않을 계획이므로 <a href="https://docs.aws.amazon.com/linux/al2/ug/set-hostname.html" target="_blank" rel="noreferrer">서버 재부팅 시 호스트이름 고정을 위한 설정</a>은 진행하지 않았습니다.</p><h4 id="사용자-데이터의-cloud-config-로-호스트이름-지정" tabindex="-1">사용자 데이터의 cloud-config 로 호스트이름 지정 <a class="header-anchor" href="#사용자-데이터의-cloud-config-로-호스트이름-지정" aria-label="Permalink to &quot;사용자 데이터의 cloud-config 로 호스트이름 지정&quot;">​</a></h4><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#cloud-config</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">hostname</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tsdb.local</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">fqdn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tsdb.local</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">manage_etc_hosts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>만약, 초기 인프라 구성 시 EC2 인스턴스를 생성하는 단계에서 호스트이름을 지정하고 싶다면 위와 같이 사용자 데이터 항목에 <u><a href="https://serverfault.com/a/787905" target="_blank" rel="noreferrer">cloud-config</a></u> 설정을 포함하여 IP 주소 기반이 아닌 원하는 호스트이름을 적용할 수 있습니다.</p><h4 id="호스트이름-변경을-위한-파일-목록" tabindex="-1">호스트이름 변경을 위한 파일 목록 <a class="header-anchor" href="#호스트이름-변경을-위한-파일-목록" aria-label="Permalink to &quot;호스트이름 변경을 위한 파일 목록&quot;">​</a></h4><p>이외의 방법을 찾아보면 EC2 인스턴스의 <u>OS 유형에 따라</u> 아래와 같은 파일을 수정해서 호스트이름을 변경할 수 있음을 알 수 있습니다.</p><ul><li>/etc/hostname</li><li>/etc/hosts</li><li>/etc/sysconfig/network</li><li>/etc/cloud/cloud.cfg</li></ul><h4 id="참고-자료" tabindex="-1">참고 자료 <a class="header-anchor" href="#참고-자료" aria-label="Permalink to &quot;참고 자료&quot;">​</a></h4><ul><li><a href="https://docs.aws.amazon.com/linux/al2/ug/set-hostname.html" target="_blank" rel="noreferrer">Change the hostname of your AL2 instance - Amazon Linux 2</a></li><li><a href="https://medium.com/@pratheekhegde/prettify-your-ec2-hostnames-1d89f4a7c76d" target="_blank" rel="noreferrer">Prettify your EC2 Hostnames</a></li><li><a href="https://docs.aws.amazon.com/linux/al2023/ug/cloud-init.html" target="_blank" rel="noreferrer">Customized cloud-init - AL2023</a></li></ul>`,13)])])}const u=s(n,[["render",l]]);export{k as __pageData,u as default};
